cypress_script:
describe('Date Picker Functionality', () => {
  it('should allow the user to select a date successfully', () => {
    cy.visit('https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').type('07/21/2026').should('have.value', '07/21/2026');
  });
  it('should not change the URL when the date input is empty', () => {
    cy.visit('https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').clear();
    cy.url().should('eq', 'https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Date Picker Functionality', () => {
  test('should allow the user to select a date successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/date-picker');
    await page.fill('#datePickerMonthYearInput', '07/21/2026');
    const inputValue = await page.inputValue('#datePickerMonthYearInput');
    expect(inputValue).toBe('07/21/2026');
  });

  test('should not change the URL when the date input is empty', async ({ page }) => {
    await page.goto('https://demoqa.com/date-picker');
    await page.fill('#datePickerMonthYearInput', '');
    expect(page.url()).toBe('https://demoqa.com/date-picker');
    await expect(page.locator('#datePickerMonthYearInput')).toBeVisible();
  });
});
